def canon(v: Any) -> str: return json.dumps(v,ensure_ascii=False,sort_keys=True,separators=(",",":"))
def norm(v: Any) -> str: return " ".join(re.findall(r"[a-záéíóúüñ0-9']+",str(v).casefold()))
def hashed(x: dict[str,Any]) -> dict[str,Any]:
    x["contentHash"]="sha256:"+hashlib.sha256(canon({k:v for k,v in x.items() if k not in {"id","contentHash"}}).encode()).hexdigest(); return x
def base(i,fmt,prompt,c,pool,feedback,**kw):
    hint=kw.pop("hint",None); req=kw.pop("requires",None); extra=kw.pop("originExtra",None); scoring=kw.pop("scoring",None)
    o={"kind":"editorial","feedback":{"es":feedback}}
    if pool=="practiceGuided": o["hint"]={"es":hint or "Observa el verbo y la forma que lo sigue."}
    if extra: o.update(extra)
    if scoring: o["scoring"]=scoring
    return {"id":i,"format":fmt,"prompt":{"es":prompt},"answer":{},"choices":[],
            "teaches":[c] if pool=="practiceGuided" else [],"requires":[] if pool=="practiceGuided" else list(req or [c]),
            "origin":o,"attemptEvidence":{"attempt":"independent" if pool in {"evaluation","review"} else "guided","evidence":"deterministic","remediation":"editorial"},
            "accessibility":{"screenReader":True,"highContrast":True,"largeText":True}}
def q(i,prompt,choices,index,c,pool,feedback,**kw):
    x=base(i,"elegir",prompt,c,pool,feedback,**kw); x["choices"]=[{"text":z} for z in choices]; x["answer"]={"index":index}; return hashed(x)
def listen(i,prompt,audio,choices,index,c,pool,feedback,**kw):
    x=base(i,"escuchar",prompt,c,pool,feedback,**kw); x["choices"]=[{"text":z} for z in choices]; x["answer"]={"index":index}; x["origin"].update({"audio":audio,"audioMode":"tts","languageCode":"en","speedOptions":[0.75,1.0],"maxReplays":3,"revealTranscriptAfterAttempt":True}); return hashed(x)
def fill(i,prompt,answer,c,pool,feedback,**kw):
    x=base(i,"completar",prompt,c,pool,feedback,**kw); x["answer"]={"text":answer,"accepted":[answer]}; return hashed(x)
def order(i,prompt,answer,c,pool,feedback,**kw):
    x=base(i,"ordenar",prompt,c,pool,feedback,**kw); x["answer"]={"text":answer,"tokens":answer.split()}; return hashed(x)
def write(i,prompt,stim,answer,alt,c,pool,feedback,**kw):
    x=base(i,"escribir",prompt,c,pool,feedback,**kw); x["origin"]["text"]=stim; x["answer"]={"text":answer,"accepted":[answer,alt]}; return hashed(x)
def match(i,prompt,pairs,c,pool,feedback,**kw):
    x=base(i,"relacionar",prompt,c,pool,feedback,**kw); vals=[[a,{"es":b}] for a,b in pairs]; x["origin"]["pairs"]=vals; x["answer"]={"pairs":vals}; return hashed(x)
def teach(n,rows):
    out=[]
    for k,(en,es,ex) in enumerate(rows,1):
        ew,sw=en.split(),es.split(); ce,cs=max(1,len(ew)//2),max(1,len(sw)//2)
        out.append({"id":f"en.n3.class-{n:02d}.t{k:02d}","en":en,"es":es,"explanationEs":ex,
                    "segments":[{"en":" ".join(ew[:ce]),"es":" ".join(sw[:cs])},{"en":" ".join(ew[ce:]),"es":" ".join(sw[cs:])}],
                    "audioText":en,"audioMode":"tts","languageCode":"en","patternId":CONCEPTS[n]})
    return out
