def audit(classes,full=False):
    totals=Counter(); formats=Counter(); prompts=set(); sigs=set(); indices=Counter()
    for cls in classes:
        assert cls["status"]=="shadow" and cls["runtimeAi"] is False and cls["qualityPolicy"]==QUALITY
        assert 4<=len(cls["teaching"])<=6 and 6<=len(cls["vocabulary"])<=12
        localf=set(); localidx=Counter(); feedback=[]
        for pool,count in (("practiceGuided",3),("practice",3),("evaluation",4),("review",3)):
            assert len(cls["pools"][pool])==count; totals[pool]+=count
            for x in cls["pools"][pool]:
                assert len(x["prompt"]["es"])<=90; payload={k:v for k,v in x.items() if k not in {"id","contentHash"}}; assert x["contentHash"]=="sha256:"+hashlib.sha256(canon(payload).encode()).hexdigest()
                localf.add(x["format"]); formats[x["format"]]+=1; feedback.append(x["origin"]["feedback"]["es"]); assert norm(x["prompt"]["es"]) not in prompts; prompts.add(norm(x["prompt"]["es"]))
                if pool!="practiceGuided": assert "hint" not in x["origin"]
                if x["format"] in {"elegir","escuchar"}: localidx[x["answer"]["index"]]+=1; indices[x["answer"]["index"]]+=1; assert len(x["choices"])>=3
                if x["format"]=="escribir": assert len(x["answer"].get("accepted",[]))>=2
                st=x["origin"].get("audio") or x["origin"].get("text") or x["origin"].get("pairs") or x["prompt"]["es"]; sg=norm({"stimulus":st,"answer":x["answer"]}); assert sg not in sigs; sigs.add(sg)
        assert len(localf)>=4 and len(feedback)==len(set(feedback)) and len(localidx)>=2 and max(localidx.values())/sum(localidx.values())<=.60
        visible=norm({"teaching":cls["teaching"],"pools":cls["pools"]}); assert all(norm(v["en"]) in visible for v in cls["vocabulary"])
        ids={x["id"] for x in cls["pools"]["evaluation"]}; assert set(cls["remediationMap"])==ids
        tids={x["id"] for x in cls["teaching"]}; rids={x["id"] for x in cls["pools"]["review"]}
        for route in cls["remediationMap"].values(): assert route["reteach"] in tids and route["review"] in rids
        if cls["phase"] in {"production","transfer"}: assert any(len(re.findall(r"\b[\w’-]+\b",x["answer"]["text"]))>=8 and len(x["answer"].get("accepted",[]))>=2 for pool in ("evaluation","review") for x in cls["pools"][pool] if x["format"]=="escribir")
    if full:
        assert len(classes)==5 and sum(totals.values())==65; exp=[CONCEPTS[k] for k in NUMBERS]; close=classes[-1]; assert close["usesPatterns"]==exp and close["cumulativeEvaluation"]==exp
        assert all(x["requires"]==exp for x in close["pools"]["evaluation"])
        c31,c32,c33,c34=classes[:4]; c31e04=next(x for x in c31["pools"]["evaluation"] if x["id"].endswith(".e04")); assert "cinco verbos" in c31e04["prompt"]["es"].lower() and "cinco relaciones" in c31e04["origin"]["feedback"]["es"].lower() and "tres verbos" in c31["pools"]["practice"][1]["origin"]["feedback"]["es"].lower()
        c32e04=next(x for x in c32["pools"]["evaluation"] if x["id"].endswith(".e04")); assert c32e04["format"]=="relacionar" and len(c32e04["origin"]["pairs"])==6 and c32e04["origin"]["scoring"]["total"]==6 and c32e04["origin"]["scoring"]["minimumCorrect"]==5
        c33e04=next(x for x in c33["pools"]["evaluation"] if x["id"].endswith(".e04")); assert c33e04["format"]=="escuchar" and len(c33e04["origin"]["tableRows"])==4 and c33e04["origin"]["scoring"]["minimumCorrect"]>=4 and "audio" in c33e04["origin"]
        c34e04=next(x for x in c34["pools"]["evaluation"] if x["id"].endswith(".e04")); low,high=70,90; assert all(low<=len(re.findall(r"\b[\w’-]+\b",a))<=high for a in c34e04["answer"]["accepted"]); assert all("because" in a.lower() or "since" in a.lower() for a in c34e04["answer"]["accepted"])
        t06,e04,r03=close["teaching"][5],close["pools"]["evaluation"][3],close["pools"]["review"][2]
        assert "community group" in t06["en"].lower() and "library" not in e04["origin"].get("text","").lower() and "familia" in r03["origin"].get("text","").lower()
        assert len(re.findall(r"\b[\w’-]+\b",e04["answer"]["text"])) in range(80,111) and len(re.findall(r"\b[\w’-]+\b",r03["answer"]["text"])) in range(80,111)
        assert len({t06["en"],e04["origin"].get("text",""),r03["origin"].get("text","")})==3; et=e04["answer"]["text"].lower(); assert "enjoys gardening" in et and "avoids using" in et and "wants to" in et and "plans to" in et and "hopes to" in et
